// ---------- offers (>=1 per store so every store page is indexable) ----------
const DISCO = ['10% off', '15% off', '20% off', 'Up to 30% off', 'Free delivery', '25% off', 'Extra 10% off', '£10 off', 'Top-rated deal'];
const VER = ['2026-10-20', '2026-10-24', '2026-10-27', '2026-10-29', '2026-10-31', '2026-11-01'];
const coupons = [];
stores.forEach((s, i) => {
  const disc = DISCO[i % DISCO.length];
  const vat = VER[i % VER.length];
  coupons.push({
    id: 'c-' + s.slug + '-deal', storeSlug: s.slug, title: `${s.name}: ${disc}`, type: 'deal', code: '', discount: disc,
    description: `Sample ${s.name} offer. Replace it with a live deal in the CMS before promoting it.`, expires: '2026-12-31',
    verified: true, verifiedAt: vat, markets: s.markets, status: 'published', demo: true, featured: s.featured, url: '',
    terms: 'Sample offer - confirm current terms on the store website.', tags: [],
  });
  if (i % 3 === 0) {
    coupons.push({
      id: 'c-' + s.slug + '-code', storeSlug: s.slug, title: `${s.name}: 20% off with code`, type: 'code', code: 'SAMPLE20', discount: '20% off',
      description: `Sample promo code for ${s.name}. Replace the code and terms in the CMS before going live.`, expires: '2026-12-31',
      verified: true, verifiedAt: vat, markets: s.markets, status: 'published', demo: true, featured: false, url: '',
      terms: 'Sample code - exclusions may apply.', tags: [],
    });
  }
});

