const A = 'CouponBuz Team';
const POSTS = [
  { slug: 'how-to-tell-if-a-promo-code-will-work', title: 'How to Tell If a Promo Code Will Work Before You Use It', excerpt: 'Five quick checks that save you from dead codes, hidden exclusions and surprise renewal prices.', author: A, date: '2026-10-01', status: 'published', image: '', seoTitle: 'How to Tell If a Promo Code Will Work (5 Quick Checks)', seoDescription: 'Learn five quick checks to spot expired, restricted or misleading promo codes before you reach checkout and waste your time.',
    body: "A code that fails at checkout wastes your time and can nudge you into paying full price. These five checks take under a minute.\n\n## 1. Look for a recent check date\nA code with no date is a guess. Prefer listings that say when they were last tested and drop anything older than a few weeks for fast-moving retailers.\n\n## 2. Read the exclusions\nMost percentage codes exclude sale items, gift cards or certain brands. If your basket is mostly excluded items, the code will not apply.\n\n## 3. Check the minimum spend\nA code that needs a high basket total may push you to buy more than you planned. Work out whether the saving is still worth it.\n\n## 4. Confirm region and account rules\nMany codes work only in one country or only for new customers. A US-only code will be rejected if you shop from the UK.\n\n## 5. Look at the renewal price\nFor subscriptions, the first-term discount is often the headline. Note what the service charges after that period before you enter payment details.\n\nIf a code still fails, clear the basket, re-enter it exactly as shown and make sure you are signed in to the right account." },
  { slug: 'best-time-to-buy-sales-calendar', title: 'The Best Time to Buy Almost Anything: A Sales Calendar', excerpt: 'A month-by-month guide to when TVs, mattresses, fashion and flights are cheapest.', author: A, date: '2026-09-22', status: 'published', image: '', seoTitle: 'Best Time to Buy: A Month-by-Month Sales Calendar', seoDescription: 'Use this month-by-month sales calendar to time big purchases like TVs, mattresses, fashion and flights for the lowest prices.',
    body: "Retailers follow predictable sale patterns. Time your purchase around them and you can save without chasing every coupon.\n\n## January\nNew-year clearance and white-goods sales. Retailers reset stock, so sofas, bedding and winter clothing drop sharply.\n\n## Spring\nGarden and DIY events, plus Easter promotions on food and travel. Book summer flights early.\n\n## Summer\nMid-season fashion sales and Prime Day style events. Electronics and outdoor gear see good knock-downs.\n\n## Black Friday and Cyber Monday\nThe biggest tech, gaming and appliance discounts. Compare against pre-sale prices to avoid inflated discounts.\n\n## December\nGift sets and partywear peak early, then drop right after Christmas into Boxing Day sales.\n\n## Rule of thumb\nBuy out of season where you can. A winter coat is cheapest in spring, and a summer fan is cheapest in autumn." },
  { slug: 'how-to-stack-coupons-cashback-loyalty', title: 'How to Stack Coupons, Cashback and Loyalty Points', excerpt: 'Layer multiple savings methods legally without breaking a store rules.', author: A, date: '2026-09-15', status: 'published', image: '', seoTitle: 'How to Stack Coupons, Cashback and Loyalty Legally', seoDescription: 'Learn how to combine discount codes, cashback and loyalty points in the right order to save the most, without breaking store terms.',
    body: "Stacking savings is about order and the rules. Do it right and a single purchase can be cheaper by more than one discount.\n\n## Start with the price\nBuy at the lowest base price first. A code on an inflated price is not a saving.\n\n## Apply the code, then loyalty\nEnter the promo code at checkout, then collect loyalty points on the amount you actually pay.\n\n## Add cashback last\nClick through a cashback site after you have your basket ready. It tracks the final paid amount, so resolve codes first.\n\n## Know the limits\nMany stores exclude cashback on orders paid partly with gift cards, or void cashback if you use a third-party code. Read each program rules.\n\n## Keep records\nScreenshot the code and the confirmed order total. If cashback fails to track, you have the evidence to claim it." },
  { slug: 'student-discount-guide', title: 'Student Discounts: Every Place That Gives You Money Off', excerpt: 'Verify your student status once and unlock year-round discounts on tech, fashion and food.', author: A, date: '2026-09-08', status: 'published', image: '', seoTitle: 'Student Discount Guide: Tech, Fashion and Food Savings', seoDescription: 'A complete student discount guide covering how to verify status and where to save on tech, fashion, software, food and travel.',
    body: "Student discounts are often bigger than public promo codes and available all year. Verifying once unlocks most of them.\n\n## Verify once\nServices like a student ID card or an online verification tool confirm your status to many retailers at once.\n\n## Tech and software\nApple, Microsoft and Adobe run education stores. Laptops and creative software are frequently the biggest wins.\n\n## Fashion and sportswear\nMany high-street and sportswear brands offer 10 to 15 percent off for students, often stackable with sale prices.\n\n## Food and travel\nDelivery apps and railcards give steady student rates that add up over a term.\n\n## Read the rules\nMost student codes exclude other promotions and cannot be combined with cashback. Check before you rely on a stack." },
  { slug: 'black-friday-2026-preparation-guide', title: 'Black Friday 2026: How to Prepare and Avoid Fake Deals', excerpt: 'A practical checklist to spot inflated discounts and buy only what you actually need.', author: A, date: '2026-10-29', status: 'published', image: '', seoTitle: 'Black Friday 2026: Prepare and Avoid Fake Deals', seoDescription: 'Get ready for Black Friday 2026 with a checklist to track prices, spot inflated discounts and buy only genuine bargains.',
    body: "Black Friday rewards preparation more than impulse. A little work now means you recognise a real deal when you see one.\n\n## Build a shortlist now\nWrite down the exact models you want. Vague wishes invite impulse buys.\n\n## Record today prices\nNote current prices in a spreadsheet. On the day, compare against your notes, not the slashed sticker price.\n\n## Watch for inflate-then-discount\nSome retailers raise prices weeks before the event. Price-history tools expose this quickly.\n\n## Set a hard budget\nDecide the total you will spend and stick to it. Bundles and add-ons are where budgets break.\n\n## Check delivery and returns\nA great price is no good if delivery arrives after the date you need it, or returns are excluded." },
  { slug: 'cyber-monday-vs-black-friday', title: 'Cyber Monday vs Black Friday: Which Has Better Deals?', excerpt: 'Where each event wins, and how to shop both without overpaying.', author: A, date: '2026-10-26', status: 'published', image: '', seoTitle: 'Cyber Monday vs Black Friday: Which Is Better?', seoDescription: 'Compare Cyber Monday and Black Friday to see which has better deals on tech, fashion and home, and how to shop both smartly.',
    body: "The two biggest online shopping days overlap in stock but differ in focus. Knowing the split helps you wait for the right moment.\n\n## Black Friday strengths\nIn-store doorbusters, big-ticket electronics and appliances. Inventory is deepest, but the best prices are often limited stock.\n\n## Cyber Monday strengths\nOnline-only offers, software, small electronics and fashion. Retailers extend weekend deals and add fresh online codes.\n\n## Where they overlap\nMost tech and home deals run across the whole weekend, so you do not have to buy on a single day.\n\n## Strategy\nShortlist early, track prices through both days, and buy when the price hits your target rather than guessing which day wins.\n\n## Do not forget returns\nExtended holiday return windows often apply, but confirm the dates for anything bought as a gift." },
  { slug: 'how-cashback-sites-work', title: 'How Cashback Sites Really Work (And When They Beat Coupons)', excerpt: 'Understand tracking, payout windows and why cashback sometimes fails.', author: A, date: '2026-09-29', status: 'published', image: '', seoTitle: 'How Cashback Sites Work and When They Beat Coupons', seoDescription: 'Understand how cashback sites track purchases, when they pay out and why cashback sometimes fails, so you can use them with confidence.',
    body: "Cashback returns a slice of your spend, but the mechanics matter if you want it to actually arrive.\n\n## How tracking works\nYou click through the cashback site to the retailer. A tracking cookie records the order, and the retailer confirms it later.\n\n## Why it fails\nAd blockers, coupon extensions, paying with a gift card or returning items can void cashback. Start clean and avoid other codes unless allowed.\n\n## When payout arrives\nMost sites wait until the retailer confirms and the return window closes. Expect weeks, not days.\n\n## Cashback vs coupon\nA coupon gives an instant discount; cashback arrives later. When both are allowed, using the coupon first and cashback second usually saves most.\n\n## Track your claims\nKeep order confirmations so you can chase missing cashback before the claim window closes." },
  { slug: 'free-delivery-codes-guide', title: 'Free Delivery Codes: How to Never Pay for Shipping Again', excerpt: 'Thresholds, memberships and codes that wipe out delivery fees.', author: A, date: '2026-09-19', status: 'published', image: '', seoTitle: 'Free Delivery Codes: How to Avoid Shipping Fees', seoDescription: 'Learn how free delivery codes, spending thresholds and memberships work so you can stop paying for shipping on online orders.',
    body: "Delivery fees quietly erode a discount. A few habits keep shipping free.\n\n## Know the threshold\nMany stores ship free over a set basket total. If you are close, add a genuinely useful item rather than paying delivery.\n\n## Look for delivery codes\nRetailers often release free-delivery codes around sales. These stack well because they do not usually reduce the item price.\n\n## Consider memberships\nIf you order often, a delivery membership can pay for itself over a year. Do the maths on your order frequency.\n\n## Collect in store\nClick and Collect is often free and faster than waiting for a courier.\n\n## Watch the small print\nBulky items, islands and next-day slots are often excluded from free delivery. Check before you rely on it." },
  { slug: 'how-to-spot-a-fake-discount', title: 'How to Spot a Fake Discount (and Price-Anchoring Tricks)', excerpt: 'The psychology retailers use to make a price look lower than it is.', author: A, date: '2026-09-11', status: 'published', image: '', seoTitle: 'How to Spot a Fake Discount and Price Anchoring', seoDescription: 'Discover the price-anchoring and fake-discount tricks retailers use, and learn simple checks to confirm a deal is genuinely good.',
    body: "A crossed-out price is a claim, not a fact. These tricks are common and easy to see once you know them.\n\n## Inflate-then-discount\nSome stores raise prices before a sale so the discount looks bigger. Price history exposes it in seconds.\n\n## The anchor price\nShowing a high original price makes the sale price feel like a bargain, even when the item is rarely sold at full price.\n\n## Bundle padding\nFree extras can hide a higher base price. Compare the item alone across retailers.\n\n## Countdown pressure\nTimers and low-stock flags push quick decisions. Step away and check the price elsewhere.\n\n## The simple test\nAsk what you would pay elsewhere today. If the answer is similar, the discount is cosmetic." },
  { slug: 'do-coupon-codes-work-on-sale-items', title: 'Do Coupon Codes Actually Work on Sale Items?', excerpt: 'Why most codes exclude sale stock, and how to find ones that do not.', author: A, date: '2026-09-02', status: 'published', image: '', seoTitle: 'Do Coupon Codes Work on Sale Items? What to Know', seoDescription: 'Find out whether promo codes work on sale items, why many exclude clearance stock, and how to find codes that do stack with reductions.',
    body: "One of the most common checkout frustrations is a code that will not apply to discounted items. Here is why, and what to do.\n\n## Why codes exclude sale items\nRetailers protect margins on already-reduced stock, so terms often exclude clearance categories.\n\n## Where codes do stack\nSome stores allow codes on full-price items plus free delivery on everything. Read the terms line to see what is included.\n\n## Try a different code\nIf a percentage code fails on sale items, a free-delivery or spend-and-save code may still work.\n\n## Watch the basket order\nSometimes applying a code before adding an item makes it stick. Re-add items in a different order if a code misbehaves.\n\n## When to skip it\nIf the sale price is already the lowest you have seen, a failing code is not a reason to wait." },
  { slug: 'newsletter-only-discount-codes', title: 'Newsletter-Only Discount Codes: How to Get Them Fast', excerpt: 'The signup codes most shoppers never see, and how to use them well.', author: A, date: '2026-08-28', status: 'published', image: '', seoTitle: 'Newsletter-Only Discount Codes: How to Get Them', seoDescription: 'Discover how to find newsletter-only discount codes, what welcome offers usually include and how to use them without cluttering your inbox.',
    body: "Many of the best first-order codes are sent only to email subscribers. A few habits get you there quickly.\n\n## The welcome code\nMost stores email a first-order discount within minutes of signup. Use a separate email address to keep your main inbox clean.\n\n## Pop-ups and exit offers\nStores often show a signup prompt as you leave. These frequently contain the highest first-order discounts.\n\n## Use them once, wisely\nWelcome codes usually apply to one order, so plan a larger basket rather than a small test purchase.\n\n## Unsubscribe after\nYou can opt out once you have the code and still use it, unless the terms say otherwise.\n\n## Watch the expiry\nMany welcome codes expire within a week or two. Check the date before you save it for later." },
  { slug: 'abandoned-cart-discount-emails', title: 'Abandoned Cart Emails: How to Trigger a Discount', excerpt: 'A gentle way to nudge a better price on something you nearly bought.', author: A, date: '2026-08-21', status: 'published', image: '', seoTitle: 'Abandoned Cart Emails: How to Trigger a Discount', seoDescription: 'Learn how abandoned cart emails work and how to use them politely to unlock a discount code on items you nearly bought.',
    body: "Retailers would rather recover a near-sale than lose it, and many send a code to win you back. Use this with restraint.\n\n## How it works\nAdd items, sign in if you have an account, reach checkout and stop before paying. Many stores follow up with a reminder, sometimes with a code.\n\n## Give it a day\nCodes usually arrive within 24 to 48 hours. Wait before buying at full price.\n\n## Do not abuse it\nRepeatedly abandoning carts can get you flagged. Use it occasionally on genuine purchases.\n\n## Compare the offer\nAn abandoned-cart code may be smaller than a welcome code. Check which is larger before you choose.\n\n## Finish the purchase\nIf no code arrives, decide whether the item is worth full price. Do not let the tactic talk you into a purchase." },
  { slug: 'browser-extensions-find-coupon-codes', title: 'Browser Extensions That Find Working Codes (Safely)', excerpt: 'How coupon extensions work, what they track and when to disable them.', author: A, date: '2026-08-14', status: 'published', image: '', seoTitle: 'Coupon Browser Extensions: How They Work and Stay Safe', seoDescription: 'Understand how coupon browser extensions find codes, what browsing data they can access and how to use them safely at checkout.',
    body: "Coupon extensions test codes automatically at checkout. They can save time, but understand the trade-offs.\n\n## How they test codes\nThe extension tries a list of codes in the promo box and keeps whichever reduces the total.\n\n## The privacy trade-off\nMany extensions can read the pages you visit. Check permissions and reviews, and remove ones you no longer use.\n\n## Conflicts with cashback\nSome extensions interfere with cashback tracking. Disable the extension before clicking through a cashback site.\n\n## Verify the discount\nConfirm the applied code actually lowered the price rather than triggering a different offer.\n\n## Best practice\nKeep one trusted extension, review its permissions and turn it off for sensitive sites." },
  { slug: 'price-tracking-tools-guide', title: 'Price Tracking Tools: Buy at the Real Lowest Price', excerpt: 'Set alerts and watch history so you buy on the dip, not the spike.', author: A, date: '2026-08-07', status: 'published', image: '', seoTitle: 'Price Tracking Tools: Buy at the Real Lowest Price', seoDescription: 'Use price tracking tools and alerts to see a product price history and buy at the genuine lowest price instead of a fake discount.',
    body: "Price trackers turn guesswork into data. They show what an item really sells for over time.\n\n## See the history\nA price-history chart shows the usual selling price and the genuine lows. A sale that sits above the usual price is not a bargain.\n\n## Set alerts\nAdd the products you want and get an email when the price drops below your target.\n\n## Time the sales\nTrackers reveal when a store usually discounts, so you know whether to buy now or wait.\n\n## Combine with codes\nTrack price and codes together. The best moment is often a genuine low plus a working code.\n\n## Do not over-wait\nIf an item is already at its historical low and you need it, waiting for a few percent more can backfire." },
  { slug: 'boxing-day-january-sales-guide', title: 'Boxing Day and January Sales: A Shoppers Guide', excerpt: 'Where the deepest post-Christmas discounts really are.', author: A, date: '2026-08-01', status: 'published', image: '', seoTitle: 'Boxing Day and January Sales: A Shoppers Guide', seoDescription: 'A shoppers guide to Boxing Day and January sales, covering where the deepest discounts appear and how to avoid leftover low-quality stock.',
    body: "The post-Christmas sales can be the best of the year, or a trap of leftover stock. A little care keeps you on the right side.\n\n## What drops most\nWinter clothing, bedding, gift sets and last-season electronics fall the most as stores clear space.\n\n## Watch for low-quality stock\nSome sale items are made specifically for the event. Check model numbers and reviews, not just the price.\n\n## Use the January reset\nNew-year clearance on home and white goods often beats Black Friday for older models.\n\n## Keep gift receipts\nIf you are buying gifts early for next year, confirm the return window still applies.\n\n## Set a budget\nPost-holiday fatigue makes overspending easy. Decide your total before you browse." },
  { slug: 'best-deals-flights-hotels', title: "How to Get the Best Deals on Flights and Hotels", excerpt: "Booking windows, flexible dates and member rates that cut travel costs.", author: A, date: '2026-07-24', status: 'published', image: '', seoTitle: "How to Get the Best Deals on Flights and Hotels", seoDescription: "Learn how flexible dates, booking windows and member rates can cut the cost of flights and hotels, plus how to spot genuine travel deals.",
    body: "Travel deals reward flexibility and timing more than codes. A few strategies consistently lower the price.\n\n## Be flexible on dates\nShifting by a day or two often changes a fare by a large margin. Fare calendars make this visible.\n\n## Book in the right window\nDomestic flights often price best a few weeks out, while long-haul and holiday travel reward earlier booking.\n\n## Use member rates\nHotel chains and booking sites give signed-in members lower prices than public listings.\n\n## Compare the full cost\nBaggage, transfers and resort fees can erase a cheap headline fare. Compare the all-in total.\n\n## Set price alerts\nTrack a route or hotel and book when the price dips to your target, rather than guessing." },
  { slug: 'membership-vs-coupon-worth-it', title: "Membership vs Coupon: Is a Paid Subscription Worth It?", excerpt: "Run the break-even maths before you pay for a loyalty or delivery plan.", author: A, date: '2026-07-17', status: 'published', image: '', seoTitle: "Membership vs Coupon: Is a Paid Subscription Worth It?", seoDescription: "Work out whether a paid loyalty, delivery or warehouse membership beats using free coupons by running a simple break-even calculation.",
    body: "Paid memberships can beat coupons, but only if you use them enough. The maths is simple once you know your habits.\n\n## Count your orders\nIf a delivery membership saves per order, estimate how many orders you place a month and multiply.\n\n## Add the perks\nFree delivery, member prices and early access all count. Estimate a realistic value, not the best case.\n\n## Find the break-even\nDivide the annual fee by the per-order saving to see how many orders you need to break even.\n\n## Compare with free codes\nA free code or welcome offer may cover your occasional purchases without a commitment.\n\n## Review yearly\nCancel if your usage drops. A membership you forget to use is a cost, not a saving." },
  { slug: 'price-matching-save-more', title: "How to Use Competitor Price Matching to Save More", excerpt: "Make retailers honour a lower price elsewhere, without a code.", author: A, date: '2026-07-10', status: 'published', image: '', seoTitle: "How to Use Price Matching to Save More", seoDescription: "Learn how retailer price matching works, which stores offer it and how to claim a lower competitor price quickly and reliably at checkout.",
    body: "Price matching lets you get a competitor's lower price from the store you prefer. It is often faster than hunting for a code.\n\n## Know who offers it\nMany electronics, home and department stores price match. Check the policy before you buy.\n\n## Have proof ready\nKeep a live link or screenshot of the identical item at the lower price, including size and colour.\n\n## Match the right item\nThe competitor item must be identical and in stock. Bundles and marketplace sellers are often excluded.\n\n## Do it before checkout\nSome stores match at the point of sale, others refund the difference after. Ask which applies.\n\n## Combine where allowed\nIf the policy allows, apply a code after the match for extra savings, but confirm the rules first." },
  { slug: 'first-order-discounts-list', title: "First-Order Discounts: The Complete New-Customer Guide", excerpt: "How to claim welcome offers without creating clutter or missing expiry.", author: A, date: '2026-07-03', status: 'published', image: '', seoTitle: "First-Order Discounts: New-Customer Deals Guide", seoDescription: "A complete guide to first-order and new-customer discounts: how to find them, when they apply and how to use them before they expire.",
    body: "New-customer offers are among the largest discounts available, but they come with rules. Plan to use them well.\n\n## Where to find them\nSignup pop-ups, app installs and newsletter forms usually carry the best welcome codes.\n\n## One per customer\nMost are limited to one per person or household. Do not count on repeating them.\n\n## Use on a meaningful basket\nApply the welcome code to a purchase you actually want, so the saving is real.\n\n## Check the expiry\nWelcome codes often expire within days. Note the date the moment you get it.\n\n## Mind the minimum spend\nSome first-order codes require a minimum basket. Make sure you were going to spend that anyway." },
  { slug: 'cancel-subscriptions-avoid-renewal-jumps', title: "How to Cancel Subscriptions and Avoid Renewal Jumps", excerpt: "Stop paying full price when a cheap first year quietly renews.", author: A, date: '2026-06-26', status: 'published', image: '', seoTitle: "Cancel Subscriptions: Avoid Renewal Price Jumps", seoDescription: "Learn how to track subscription renewals, cancel before a price jump and re-qualify for introductory offers without losing what you need.",
    body: "Introductory prices are designed to renew higher. A little tracking keeps subscriptions cheap.\n\n## Note every renewal date\nList subscriptions with their renewal dates and prices so nothing renews by surprise.\n\n## Cancel before the jump\nSet a reminder a week before renewal. Many services let you cancel and keep access until the period ends.\n\n## Re-qualify where allowed\nSome services offer a returning-customer deal after a break. Check the terms before relying on it.\n\n## Downgrade instead\nA lower tier often covers what you actually use. Review usage before renewal.\n\n## Use virtual cards\nA virtual card with a set limit prevents surprise charges and makes cancelling cleaner." },
  { slug: 'gift-card-discounts-guide', title: "Gift Card Discounts: Where to Buy Them for Less", excerpt: "Pay less than face value on cards you will actually spend.", author: A, date: '2026-06-19', status: 'published', image: '', seoTitle: "Gift Card Discounts: Where to Buy Them for Less", seoDescription: "Find out where to buy discounted gift cards, how to check balances safely and how to combine them with coupons for extra savings.",
    body: "Discounted gift cards are a quiet way to save on stores you already use. A few safeguards keep it safe.\n\n## Buy below face value\nRetailers and resellers sometimes sell cards at a discount. Combine with a store code for a double saving.\n\n## Check the balance first\nIf buying a resold card, verify the balance immediately and keep the receipt.\n\n## Watch expiry and fees\nSome cards carry inactivity fees or expiry dates. Read the terms before you buy.\n\n## Use soon\nA gift card you forget is money lost. Buy for a planned purchase, not speculatively.\n\n## Mind the cashback rule\nOrders paid partly with gift cards may not earn cashback. Check the program terms." },
  { slug: 'back-to-school-shopping-save', title: "Back-to-School Shopping: Save on Tech, Clothes and Supplies", excerpt: "A term-start checklist that spreads cost without overspending.", author: A, date: '2026-06-12', status: 'published', image: '', seoTitle: "Back-to-School Shopping: Save on Tech and Supplies", seoDescription: "A back-to-school savings checklist covering laptops, clothing and stationery, plus student discounts and timing tips to cut term-start costs.",
    body: "Term-start costs add up fast. A short plan keeps the total down.\n\n## Buy tech with education pricing\nLaptops and software often have education stores that beat public codes.\n\n## Shop the sales calendar\nLate summer sales and tax-free weekends (where offered) are ideal for clothing and supplies.\n\n## Bulk buy basics\nStationery and socks are cheaper in multi-packs. Split with other families if packs are large.\n\n## Reuse where sensible\nLast year bags and PE kits often survive. Put the saving toward the items that matter.\n\n## Use student status\nVerify once and use student discounts on clothing, tech and food through the term." },
  { slug: 'amazon-prime-day-real-savings', title: "Amazon Prime Day: How to Get Real Savings", excerpt: "Which categories actually drop, and how to avoid the noise.", author: A, date: '2026-06-05', status: 'published', image: '', seoTitle: "Amazon Prime Day: How to Get Real Savings", seoDescription: "Learn which categories genuinely drop on Prime Day, how to track prices and how to avoid impulse buys during the two-day sales event.",
    body: "Prime Day is loud, but not every deal is good. Focus on the categories that really drop.\n\n## What genuinely discounts\nAmazon devices, small electronics, headphones and home gadgets tend to fall the most.\n\n## Check price history\nConfirm the deal is below the usual price, not just below a raised list price.\n\n## Prefer lightning deals you planned for\nUse a wishlist so you only chase discounts on items you already wanted.\n\n## Watch bundle pricing\nBundles can hide a higher unit price. Compare the item alone.\n\n## Do not buy just because\nA discount on something you do not need is not a saving. Stick to your list." },
  { slug: 'how-to-complain-get-refund', title: "How to Complain and Get a Refund: Your Consumer Rights", excerpt: "A calm, step-by-step way to resolve a bad purchase.", author: A, date: '2026-05-29', status: 'published', image: '', seoTitle: "How to Complain and Get a Refund: Consumer Rights", seoDescription: "A step-by-step guide to complaining about a purchase and getting a refund, covering your consumer rights, chargebacks and escalation routes.",
    body: "When something goes wrong, a clear paper trail gets faster results than anger. Follow these steps.\n\n## Know your rights\nMost regions give a right to a refund, repair or replacement for faulty goods. Check the rules where you live.\n\n## Contact the retailer first\nUse written channels and state the order number, the problem and the outcome you want.\n\n## Keep evidence\nSave photos, messages and receipts. A concise summary with evidence is hard to ignore.\n\n## Escalate if needed\nIf the retailer stalls, a card chargeback or a consumer body can help. Note the deadlines.\n\n## Stay factual\nCalm, specific complaints get resolved faster than emotional ones." },
  { slug: '30-day-rule-time-big-purchases', title: "The 30-Day Rule: How to Time Big Purchases", excerpt: "A simple waiting rule that stops impulse buys and catches real discounts.", author: A, date: '2026-05-22', status: 'published', image: '', seoTitle: "The 30-Day Rule: How to Time Big Purchases", seoDescription: "Use the 30-day rule to avoid impulse buys, track prices on big purchases and buy only when a discount is genuinely worth it.",
    body: "Big purchases are where small decisions matter most. A waiting rule removes the pressure to buy on impulse.\n\n## Write it down\nWhen you feel the urge to buy, note the item and the date. Wait 30 days before deciding.\n\n## Track the price meanwhile\nA price tracker during the wait shows whether the price really moves or the discount is cosmetic.\n\n## Decide with a clear head\nAfter the wait, if you still want it and the price is right, buy with confidence.\n\n## Let sales come to you\nWaiting often lines up with a seasonal sale or a working code, so you rarely lose out.\n\n## Break the rule rarely\nGenuine limited-time clearance is the exception. Use the rule everywhere else." },
];

// ---------- extra static / SEO pages ----------
const NEW_PAGES = [
  { slug: 'faq', title: 'Coupon FAQ: Frequently Asked Questions', status: 'published', seoTitle: 'Coupon FAQ: Frequently Asked Questions', seoDescription: 'Answers to common questions about promo codes, voucher expiry, regions, cashback and how CouponBuz checks offers before publishing.', body: "## Are the codes free to use?\nYes. CouponBuz is free. We may earn a commission when you buy through a link, and it never changes the price you pay.\n\n## Why did a code not work?\nCodes can expire, need a minimum spend, or apply only to new customers or one country. Check the terms line on each offer.\n\n## Which countries are covered?\nOffers are tagged for the US, UK, Canada and Europe, and each offer shows the regions it is valid in.\n\n## How often are offers checked?\nEvery offer shows when it was last checked, and expired offers are removed when the site is updated. See [how we verify offers](/how-we-verify/).\n\n## Can I submit a code?\nYes. Use the [submit page](/submit-coupon/) and a person reviews every submission before anything is published." },
  { slug: 'editorial-policy', title: 'Editorial Policy', status: 'published', seoTitle: 'Editorial Policy: How We Choose and Check Offers', seoDescription: 'Our editorial policy explains how we decide which stores and offers to feature, how we check them and how corrections are handled.', body: "Our goal is to list offers that are genuinely useful, with clear terms and honest claims.\n\n## What we publish\nWe list offers from established retailers with a clear discount, an expiry date where possible and readable terms.\n\n## How we check\nWe test and review offers regularly. Each listing shows a last-checked date, and we remove offers that stop working.\n\n## Corrections\nIf you spot an error, please [contact us](/contact/). We fix mistakes quickly and note significant corrections.\n\n## Independence\nEditorial choices are separate from commercial relationships. Read [how we make money](/how-we-make-money/)." },
  { slug: 'how-we-test-coupons', title: 'How We Test Coupons', status: 'published', seoTitle: 'How We Test Coupons Before Publishing', seoDescription: 'A look at our testing method: how we check that a promo code works, record the discount and confirm the terms before an offer goes live.', body: "Testing is what separates a real offer from a guess. Here is how we do it.\n\n## Reproduce the offer\nWe apply the code to a realistic basket, not a contrived one, to confirm the discount applies.\n\n## Record the specifics\nWe note the discount amount, minimum spend, eligible items and expiry so the terms line is accurate.\n\n## Recheck regularly\nFast-moving stores are rechecked often. Offers past their check window are updated or removed.\n\n## Keep it honest\nIf an offer only works for new customers or one region, we say so clearly on the listing." },
  { slug: 'saving-tips', title: 'Money-Saving Tips: Cut the Cost of Everything', status: 'published', seoTitle: 'Money-Saving Tips to Cut the Cost of Everything', seoDescription: 'Practical money-saving tips that work with coupons: timing, cashback, price tracking and avoiding impulse buys on everyday spending.', body: "Saving well is a set of habits, not a single coupon. These tips compound.\n\n## Time your purchases\nBuy out of season and around predictable sales. Our [saving guides](/guides/) show a month-by-month calendar.\n\n## Stack legally\nUse a code first, then loyalty points, then cashback. Respect each program rules to keep your savings.\n\n## Track prices\nA quick price check stops you paying a fake discount. Buy on a genuine dip, not a raised list price.\n\n## Avoid impulse buys\nThe 30-day rule for big purchases rarely costs you a better price and often saves you from a mistake." },
  { slug: 'coupon-glossary', title: 'Coupon Glossary: Key Terms Explained', status: 'published', seoTitle: 'Coupon Glossary: Promo Code Terms Explained', seoDescription: 'A plain-English coupon glossary covering promo code, voucher code, cashback, stacking, minimum spend, and other common shopping terms.', body: "Shopping jargon can be confusing. Here are the terms you will see most.\n\n## Promo code / voucher code\nA code entered at checkout to reduce the price. Region names differ: the UK often says voucher code.\n\n## Cashback\nA share of your spend returned later through a cashback site, after the retailer confirms the order.\n\n## Stacking\nCombining more than one saving, such as a code plus loyalty points, where the store allows it.\n\n## Minimum spend\nThe basket total you must reach for a code to apply.\n\n## Price anchoring\nShowing a high original price to make a sale price feel like a bargain." },
  { slug: 'affiliate-disclosure', title: 'Affiliate Disclosure', status: 'published', seoTitle: 'Affiliate Disclosure', seoDescription: 'Our affiliate disclosure explains how CouponBuz earns commission on some links and how that affects the price you pay and what we list.', body: "Transparency matters. This page explains our commercial relationships.\n\n## How we earn\nCouponBuz may earn a commission when you click a link and make a purchase. This never changes the price you pay.\n\n## What it does not affect\nCommission does not change which offers we list or how we test them. Editorial choices stay independent.\n\n## Our promise\nWe label sample and unverified offers clearly and remove offers that stop working. Read our [editorial policy](/editorial-policy/) for more." },
];

// ---------- merge settings + nav + seo ----------
const settings = JSON.parse(JSON.stringify(base.settings));
const footer = settings.nav.footer.map((c) => ({ ...c, links: c.links.slice() }));
const addLinks = (title, links) => { const col = footer.find((c) => c.title === title); if (col) for (const l of links) if (!col.links.some((x) => x.url === l.url)) col.links.push(l); };
addLinks('Company', [{ label: 'FAQ', url: '/faq/' }, { label: 'Editorial policy', url: '/editorial-policy/' }, { label: 'How we test coupons', url: '/how-we-test-coupons/' }, { label: 'Saving tips', url: '/saving-tips/' }, { label: 'Coupon glossary', url: '/coupon-glossary/' }]);
addLinks('Legal', [{ label: 'Affiliate disclosure', url: '/affiliate-disclosure/' }]);
settings.nav.footer = footer;
settings.seo = { ...settings.seo, defaultDescription: 'Verified promo codes and deals for the US, UK, Canada and Europe, with last-checked dates, clear terms and money-saving guides.' };

// ---------- assemble + write (keep 3 files in sync) ----------
const newSlugs = new Set(NEW_PAGES.map((p) => p.slug));
const out = { settings, categories, stores, coupons, posts: POSTS, pages: [...base.pages.filter((p) => !newSlugs.has(p.slug)), ...NEW_PAGES], collections };
fs.writeFileSync(path.join(ROOT, 'data/seed.json'), JSON.stringify(out, null, 1) + '\n');
fs.writeFileSync(path.join(ROOT, 'public/admin/seed.json'), JSON.stringify(out));
const header = '// Starter content (also served to the admin as /admin/seed.json). Generated by scripts/generate-seed.mjs.\n';
fs.writeFileSync(path.join(ROOT, 'src/seed.js'), header + 'export default ' + JSON.stringify(out, null, 1) + ';\n');
console.log(`seed written: ${categories.length} categories, ${stores.length} stores, ${coupons.length} offers, ${POSTS.length} posts, ${out.pages.length} pages, ${collections.length} collections`);

// ---------- import-ready CSVs (Admin -> Settings -> CSV import) ----------
const csvCell = (v) => { v = String(v == null ? '' : v); return /[",\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; };
const toCSV = (rows) => rows.map((r) => r.map(csvCell).join(',')).join('\n');
const expDir = path.join(ROOT, 'exports');
fs.mkdirSync(expDir, { recursive: true });
fs.writeFileSync(path.join(expDir, 'categories.csv'), toCSV([
  ['name', 'slug', 'icon', 'description', 'status'],
  ...categories.map((c) => [c.name, c.slug, c.icon, c.description, c.status])]));
fs.writeFileSync(path.join(expDir, 'stores.csv'), toCSV([
  ['name', 'slug', 'domain', 'category', 'markets', 'description', 'tips', 'featured', 'status'],
  ...stores.map((s) => [s.name, s.slug, s.domain, s.category, (s.markets || []).join('|'), s.description, (s.tips || []).join('|'), s.featured ? 'true' : 'false', s.status])]));
fs.writeFileSync(path.join(expDir, 'coupons.csv'), toCSV([
  ['title', 'storeSlug', 'type', 'code', 'discount', 'description', 'markets', 'expires', 'verified', 'verifiedAt', 'terms', 'featured', 'demo', 'status'],
  ...coupons.map((c) => [c.title, c.storeSlug, c.type, c.code, c.discount, c.description, (c.markets || []).join('|'), c.expires, c.verified ? 'true' : 'false', c.verifiedAt, c.terms, c.featured ? 'true' : 'false', c.demo ? 'true' : 'false', c.status])]));
console.log('CSVs written to exports/ (categories, stores, coupons)');
